using System.ClientModel;
using Azure.AI.OpenAI;
using Azure.Identity;
using OpenAI.Chat;

namespace MyApp.Evals.Tests;

/// <summary>
/// Resolves an IChatClient that mirrors the AppHost's
/// AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:1.
/// Reads ConnectionStrings:chat from user-secrets or env vars.
/// </summary>
internal static class AgentChatClientFactory
{
    public static IChatClient Create(string? deploymentOverride = null)
    {
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        var host = builder.Build();

        var connStr = host.Services.GetRequiredService<IConfiguration>()
            .GetConnectionString("chat");

        if (string.IsNullOrEmpty(connStr))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but ConnectionStrings:chat is not set. " +
                "Aspire's AppHost populates this at runtime, but `dotnet test` runs standalone. " +
                "Wire one of:\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).");
        }

        var parts = ParseConnectionString(connStr);
        var endpoint = parts.GetValueOrDefault("Endpoint")
            ?? throw new InvalidOperationException("ConnectionStrings:chat missing Endpoint.");
        var deployment = deploymentOverride
            ?? parts.GetValueOrDefault("DeploymentId")
            ?? "gpt-4o-mini";

        AzureOpenAIClient client;
        if (parts.TryGetValue("Key", out var key) && !string.IsNullOrEmpty(key))
            client = new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(key));
        else
            client = new AzureOpenAIClient(new Uri(endpoint), new DefaultAzureCredential());

        return client.GetChatClient(deployment).AsIChatClient();
    }

    private static Dictionary<string, string> ParseConnectionString(string connStr)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var part in connStr.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var idx = part.IndexOf('=');
            if (idx > 0)
                result[part[..idx].Trim()] = part[(idx + 1)..].Trim();
        }
        return result;
    }
}

